export default function About() {
  return (
    <div className="container">
      <div className="card">
        <h1 className="title">About Online Auction</h1>
        <p className="subtitle">How it works & who we are</p>
        <p>Post items for bidding, place live bids, and win products in real-time. Built with React, Express, MongoDB, and Socket.IO.</p>
        <p>Our mission is to make auctions simple, transparent, and fun.</p>
      </div>
    </div>
  );
}
